ALLOWED_LOCATIONS = ['eastus2', 'westeurope']
RESOURCES = [
    {'name': 'vm1', 'location': 'eastus2', 'tags': {'costCenter': 'CC01'}},
    {'name': 'vm2', 'location': 'centralus', 'tags': {'costCenter': 'CC02'}},
    {'name': 'st1', 'location': 'westeurope', 'tags': {}},
]

def evaluate(resource):
    # Deny policy first: deny wins and stops evaluation
    if resource.get('location') not in ALLOWED_LOCATIONS:
        return 'DENIED by allowed-locations'
    # Audit policy: missing costCenter tag
    if 'costCenter' not in (resource.get('tags') or {}):
        return 'AUDIT by require-costcenter'
    return 'COMPLIANT'

for resource in RESOURCES:
    print(f"{resource['name']}: {evaluate(resource)}")
